PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;
CREATE TABLE IF NOT EXISTS profiles(id TEXT PRIMARY KEY,email TEXT NOT NULL COLLATE NOCASE UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('owner','rider')),full_name TEXT NOT NULL,phone TEXT,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES profiles(id),expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS counters(name TEXT PRIMARY KEY,value INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1),business_name TEXT NOT NULL,currency_symbol TEXT NOT NULL,timezone TEXT NOT NULL,max_kg_per_load REAL NOT NULL CHECK(max_kg_per_load>0),default_delivery_days INTEGER NOT NULL,same_day_cutoff TEXT NOT NULL,daily_pickup_capacity_loads INTEGER NOT NULL,service_areas TEXT NOT NULL,booking_open INTEGER NOT NULL,hotline TEXT,facebook_url TEXT,rider_daily_default REAL NOT NULL,rider_batch_default REAL NOT NULL,message_templates TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS services(id TEXT PRIMARY KEY,name TEXT NOT NULL,price_per_load REAL NOT NULL CHECK(price_per_load>=0),active INTEGER NOT NULL DEFAULT 1,sort INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS shops(id TEXT PRIMARY KEY,name TEXT NOT NULL,phone TEXT,address TEXT,cost_per_load REAL NOT NULL CHECK(cost_per_load>=0),capacity_loads INTEGER NOT NULL CHECK(capacity_loads>0),active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS customers(id TEXT PRIMARY KEY,bag_code TEXT UNIQUE NOT NULL,full_name TEXT NOT NULL,email TEXT NOT NULL DEFAULT '',phone TEXT UNIQUE NOT NULL,area TEXT NOT NULL,address TEXT NOT NULL,landmark TEXT,lat REAL,lng REAL,booking_token TEXT UNIQUE NOT NULL,notes TEXT,blocked INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,order_no TEXT UNIQUE NOT NULL,customer_id TEXT NOT NULL REFERENCES customers(id),service_id TEXT NOT NULL REFERENCES services(id),loads INTEGER NOT NULL CHECK(loads BETWEEN 1 AND 20),bags INTEGER NOT NULL CHECK(bags BETWEEN 1 AND 20),price_per_load REAL NOT NULL,total_price REAL GENERATED ALWAYS AS(round(loads*price_per_load,2)) STORED,shop_id TEXT REFERENCES shops(id),shop_cost_per_load REAL,status TEXT NOT NULL CHECK(status IN('pending_approval','placed','picked_up','weighed','at_shop','ready','delivered','cancelled')),source TEXT NOT NULL,channel TEXT,pickup_date TEXT NOT NULL,pickup_window TEXT NOT NULL,due_date TEXT NOT NULL,deliver_to_other INTEGER NOT NULL DEFAULT 0,delivery_address TEXT,delivery_area TEXT,notes TEXT,actual_kg REAL,picked_up_at TEXT,delivered_at TEXT,cancelled_reason TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS orders_status ON orders(status);
CREATE INDEX IF NOT EXISTS orders_customer ON orders(customer_id);
CREATE INDEX IF NOT EXISTS orders_pickup ON orders(pickup_date);
CREATE TABLE IF NOT EXISTS order_events(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id TEXT NOT NULL REFERENCES orders(id),status TEXT,note TEXT,kind TEXT NOT NULL,by_user TEXT REFERENCES profiles(id),at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rider_pay(id TEXT PRIMARY KEY,date TEXT NOT NULL,rider TEXT NOT NULL REFERENCES profiles(id),pay_type TEXT NOT NULL CHECK(pay_type IN('daily','batch')),amount REAL NOT NULL CHECK(amount>=0),stops INTEGER NOT NULL,notes TEXT);
CREATE TABLE IF NOT EXISTS rider_actions(id TEXT PRIMARY KEY,by_user TEXT NOT NULL REFERENCES profiles(id),order_id TEXT NOT NULL REFERENCES orders(id),from_status TEXT NOT NULL,to_status TEXT NOT NULL,at INTEGER NOT NULL,event_id INTEGER NOT NULL REFERENCES order_events(id),undone INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,window_start INTEGER NOT NULL,count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS challenges(id TEXT PRIMARY KEY,answer_hash TEXT NOT NULL,ip_hash TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS booking_requests(id TEXT PRIMARY KEY,fingerprint TEXT NOT NULL,result TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS orders_no_delete BEFORE DELETE ON orders BEGIN SELECT RAISE(ABORT,'Cancel orders instead of deleting them'); END;
CREATE TRIGGER IF NOT EXISTS events_no_delete BEFORE DELETE ON order_events BEGIN SELECT RAISE(ABORT,'Audit events cannot be deleted'); END;
CREATE TRIGGER IF NOT EXISTS events_no_update BEFORE UPDATE ON order_events BEGIN SELECT RAISE(ABORT,'Audit events cannot be changed'); END;
-- Account-free customer recognition; only hashes are stored, never browser-readable secrets.
CREATE TABLE IF NOT EXISTS customer_devices(token_hash TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),order_id TEXT REFERENCES orders(id),submitted_first_name TEXT NOT NULL,verified INTEGER NOT NULL DEFAULT 0,booking_token_hash TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS customer_devices_order ON customer_devices(order_id);
